#include <bits/stdc++.h>
using namespace std;

// sortowanie przez scalanie + liczba inwersji (par i<j z a[i] > a[j]) w O(n log n)
long long inwersje(vector<int>& a, int l, int r) {          // zakres [l, r)
    if (r - l <= 1) return 0;
    int m = (l + r) / 2;
    long long wynik = inwersje(a, l, m) + inwersje(a, m, r);
    int j = m;
    for (int i = l; i < m; i++) {                          // ile elementów prawej części < a[i]
        while (j < r && a[j] < a[i]) j++;
        wynik += j - m;
    }
    inplace_merge(a.begin() + l, a.begin() + m, a.begin() + r);
    return wynik;
}

int main() {
    vector<int> a = {3, 1, 2, 5, 4};
    cout << inwersje(a, 0, a.size()) << '\n';               // 3: (3,1) (3,2) (5,4)
}

