    if (r - l <= 1) return;
    int m = (l + r) / 2;
    msort(a, l, m);
    msort(a, m, r);
    inplace_merge(a.begin() + l, a.begin() + m, a.begin() + r);
}

long long inv(vector<int>& a, int l, int r) {
    if (r - l <= 1) return 0;
    int m = (l + r) / 2;
    long long w = inv(a, l, m) + inv(a, m, r);
    for (int i = l, j = m; i < m; i++) {
        while (j < r && a[j] < a[i]) j++;
        w += j - m;
    }
    inplace_merge(a.begin() + l, a.begin() + m, a.begin() + r);
    return w;
}

