// DP po warstwach z dwoma wierszami: liczba ścieżek w siatce n × m (tylko w prawo/w dół)
int main() {
    int n = 3, m = 4;
    vector<long long> prev(m, 1), cur(m);
    for (int i = 1; i < n; i++) {
        cur[0] = 1;
        for (int j = 1; j < m; j++) cur[j] = cur[j - 1] + prev[j];
        swap(prev, cur);                            // O(1) zamiast kopiowania
    }
    cout << prev[m - 1] << '\n';                    // 10
}

