#include <bits/stdc++.h>
using namespace std;

int main() {
    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());   // losowe ziarno
    mt19937 stale(2024);                                                   // powtarzalny ciąg

    uniform_int_distribution<int> kostka(1, 6);       // przedział DOMKNIĘTY [1, 6]
    for (int i = 0; i < 5; i++) cout << kostka(rng) << ' ';
    cout << '\n';

    uniform_real_distribution<double> u(0.0, 1.0);    // [0, 1)
    double p = u(rng);

    vector<int> v(10);
    iota(v.begin(), v.end(), 1);
    shuffle(v.begin(), v.end(), rng);                 // losowa permutacja, O(n)

    mt19937_64 rng64(stale());
    unsigned long long duza = rng64();                // 64 losowe bity
    cout << (p >= 0 && p < 1) << ' ' << v.size() << ' ' << duza % 10 << '\n';
}

