    int seed = argc > 1 ? atoi(argv[1]) : 1;
    mt19937 rng(seed);
    auto los = [&](int a, int b) { return uniform_int_distribution<int>(a, b)(rng); };
    int n = los(1, 10);
    cout << n << '\n';
    for (int i = 0; i < n; i++) cout << los(-100, 100) << " \n"[i == n - 1];
}

